head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickListBzTpCd = ""; // 상장업무구분코드 (그리드 로우 클릭시 상장업무구분코드를 획득함)
scwin.clickBzProcsNo = ""; // 업무처리번호 (클릭된)
scwin.logicPackYn = "Y";
scwin.clickIsuCd = ""; // 종목코드(클릭된)
scwin.vListInit = true;
scwin.logicPackYn = "Y";
scwin.clickListApplntIsurNm = ""; // 상장신청인(클릭된)
scwin.clickIsuAbbrv = "";
// 화면ID

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MaxTab_01.setSelectedTabIndex(1);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70005.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_IsuSearch_onclick
 * @description img_IsuSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuSearch_onclick = function() {
    try {
        scwin.fn_SetPar = scwin.setParIsur2;
        scwin.fn_GetPar = scwin.getParIsur2;
        $c.lcd.fn_PopFindDigitalIsurAppl();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70005.img_IsuSearch_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70005.dts_List_1_OnLoadCompleted" });
    }
};

