/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        // 신규상장접수 > Grid Row Click
        if (colid === 'ISU_ABBRV') {
            await scwin.openNewWinForDgse(row, dts_List_1);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70005.grd_List_1_OnDblClick" });
    }
};

