/**
 * @method
 * @name txb_ISUR_CD_onchange
 * @description txb_ISUR_CD 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onchange = function() {
    try {
        if (txb_ISUR_CD.getValue().length === 0) {
            txb_ISUR_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70005.txb_ISUR_CD_onchange" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70005.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70005.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // Download excel data
        $c.stf.doLogSave("ULDSTF70005.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70005.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 종목명(클릭된)

/**
 * @method
 * @name listSync
 * @description 상장신청접수 에 대한 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let v_listBzTpCd = "";
    scwin.vListInit = false; // 처음 화면 로딩시 두 번 리스트 조회 안타게 하기 위함.

    // alert("txb_ISUR_CD.value:"+ txb_ISUR_CD.value);

    if (MaxTab_01.getSelectedTabIndex() === 1) {
        //  디지털증권 예비심사 청구
        v_listBzTpCd = "780";
        url += "?SCREN_ID=" + "ULDSTF70005.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalPrelmInvstRcv";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/digital/DigitalListedRcv.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 디지털증권 신규상장 청구
        v_listBzTpCd = "781";
        url += "?SCREN_ID=" + "ULDSTF70005.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceiptRcvFor781";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/digital/DigitalListedRcv.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        // 디지털증권 추가상장 예비심사
        v_listBzTpCd = "783";
        url += "?SCREN_ID=" + "ULDSTF70005.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalAddPrelmInvstRcv";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_3",
            action : "/digital/DigitalListedRcv.do",
            ref : "",
            target : "dts_List_3=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        // 디지털증권 추가상장 청구
        v_listBzTpCd = "784";
        url += "?SCREN_ID=" + "ULDSTF70005.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceiptRcvFor784";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_4",
            action : "/digital/DigitalListedRcv.do",
            ref : "",
            target : "dts_List_4=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description (신규접수)클릭된 그리드에 대한 업무처리번호 획득
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
    scwin.clickListBzTpCd = dtsObj.getCellData(Number(obj), "LIST_BZ_TP_CD");
    scwin.clickListApplntIsurNm = dtsObj.getCellData(Number(obj), "LIST_APPLNT_ISUR_NM"); // 상장신청인
    scwin.clickIsuCd = dtsObj.getCellData(Number(obj), "ISU_CD"); // 종콕코드
    scwin.clickIsuAbbrv = dtsObj.getCellData(Number(obj), "ISU_ABBRV"); // 종목약명

};

/**
 * @method
 * @name openNewWinForDgse
 * @description 상장신청접수 에 대한 상세 팝업조회
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNewWinForDgse = async function(row, dtsObj) {
    scwin.setBzProcsNo(row, dtsObj);
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        const options = {
            id: "ULDSTF70006",
            title: "상장예비심사",
            type: "browserPopup",
            width: "1060px",
            height: "820px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70006.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        const options = {
            id: "ULDSTF70007",
            title: "신규상장",
            type: "browserPopup",
            width: "1080px",
            height: "820px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70007.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        const options = {
            id: "ULDSTF70008",
            title: "추가상장예비심사",
            type: "browserPopup",
            width: "1070px",
            height: "820px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70008.gfm", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        const options = {
            id: "ULDSTF70009",
            title: "추가상장",
            type: "browserPopup",
            width: "1060px",
            height: "820px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70009.gfm", options);
    }
};

/**
 * @method
 * @name setParIsur2
 * @description 상장신청인 선택 팝업호출용
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur2 = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        await scwin.listSync();
    }
};

/**
 * @method
 * @name getParIsur2
 * @description get Par Isur2 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isurcdappl.condition";
    return arrPar.length;
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "상장예비심사", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "신규상장", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        $c.data.downloadGridViewExcel(grd_List_3, {fileName: "추가상장예비심사", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 4) {
        $c.data.downloadGridViewExcel(grd_List_4, {fileName: "추가상장", type: "8"});
    }
};
